# region: intake
def intake(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
            return out
    return out

# region: digest
def digest(xs):
    return [v * v for v in xs]

# region: fold
def fold(xs, factor=10):
    return [v * factor for v in xs]

# region: shape
def shape(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: gather
def gather(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return gather(shape(fold(digest(intake(raw)))))

